// Evidence-backed request-path tests for the Videos leaf (Phase 3.1).
//
// Generated by scripts/research/gen-31-tests.py from the rows in api.md, which in turn come from
// docs/research/apk-endpoints.md. Each test calls the method and inspects the URL that actually
// reaches `fetch`, so a rename or a route regression fails here rather than in production.

import BandlabSDK from 'bandlabx';

function makeClient(): BandlabSDK {
  return new BandlabSDK({ bearerToken: 'My Bearer Token', baseURL: 'http://127.0.0.1:4010' });
}

/** Run `fn`, capture the URL of the first request, and answer it with a stub response. */
async function captureURL(fn: (c: BandlabSDK) => Promise<unknown>): Promise<string> {
  const calls: string[] = [];
  const realFetch = globalThis.fetch;
  globalThis.fetch = (async (input: any) => {
    calls.push(typeof input === 'string' ? input : input?.url ?? String(input));
    return new Response('{}', { status: 200, headers: { 'content-type': 'application/json' } });
  }) as typeof fetch;
  try {
    await fn(makeClient()).catch(() => undefined);
  } finally {
    globalThis.fetch = realFetch;
  }
  if (!calls.length) throw new Error('no request was issued');
  return calls[0]!;
}

describe('Videos paths match the APK evidence', () => {
  test('POST /videos/{videoId}/views hits /videos/{videoId}/views', async () => {
    const url = await captureURL((c) => c.videos.addView('182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e'));
    expect(url).toContain('/videos/182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e/views');
  });

  test('POST /videos/{videoID}/views hits /videos/{videoID}/views', async () => {
    const url = await captureURL((c) => c.videos.addView('182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e'));
    expect(url).toContain('/videos/182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e/views');
  });

  test('POST /videos/{videoID}/posts hits /videos/{videoID}/posts', async () => {
    const url = await captureURL((c) => c.videos.createPost('182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e', {}));
    expect(url).toContain('/videos/182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e/posts');
  });

  test('GET /video-mix/stickers hits /video-mix/stickers', async () => {
    const url = await captureURL((c) => c.videos.listStickers({}));
    expect(url).toContain('/video-mix/stickers');
  });

  test('GET /videos/{videoID} hits /videos/{videoID}', async () => {
    const url = await captureURL((c) => c.videos.retrieve('182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e', {}));
    expect(url).toContain('/videos/182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e');
  });
});
